# PTX source for MSE reduction (float16 inputs, float32 accumulation)
PTX_SOURCE = r'''
.version 7.2
.target sm_80
.address_size 64

.visible .entry mse_kernel(
    .param .u64 pred_ptr,
    .param .u64 tgt_ptr,
    .param .u64 out_ptr,
    .param .u32 N
)
{
    // -------------------------------------------------
    // Load kernel parameters
    // -------------------------------------------------
    .reg .u64 %pred;
    .reg .u64 %tgt;
    .reg .u64 %out;
    .reg .u32 %n;

    ld.param.u64 %pred, [pred_ptr];
    ld.param.u64 %tgt,  [tgt_ptr];
    ld.param.u64 %out,  [out_ptr];
    ld.param.u32 %n,    [N];

    // -------------------------------------------------
    // Thread / block indices
    // -------------------------------------------------
    .reg .u32 %tid, %bid, %bsize, %gsize;
    mov.u32 %tid, %tid.x;
    mov.u32 %bid, %ctaid.x;
    mov.u32 %bsize, %ntid.x;
    mov.u32 %gsize, %nctaid.x;

    // global thread id = bid * bsize + tid
    .reg .u64 %gid;
    cvt.u64.u32 %gid, %tid;
    mul.lo.u64 %gid, %bsize, %bid;
    add.u64 %gid, %gid, %tid;

    // stride = total number of threads in grid
    .reg .u64 %stride;
    cvt.u64.u32 %stride, %bsize;
    mul.lo.u64 %stride, %stride, %gsize;

    // -------------------------------------------------
    // Accumulate squared differences in fp32
    // -------------------------------------------------
    .reg .f32 %sum;
    mov.f32 %sum, 0f0;

    .reg .u64 %idx;
    mov.u64 %idx, %gid;

LOOP:
    // if idx >= N exit loop
    setp.ge.u64 %p_exit, %idx, %n;
    @%p_exit bra END_LOOP;

    // load fp16 values
    .reg .f16 %a_h, %b_h;
    ld.global.f16 %a_h, [%pred + %idx*2];
    ld.global.f16 %b_h, [%tgt  + %idx*2];

    // convert to fp32
    .reg .f32 %a_f, %b_f, %diff;
    cvt.f32.f16 %a_f, %a_h;
    cvt.f32.f16 %b_f, %b_h;

    sub.f32 %diff, %a_f, %b_f;
    mul.f32 %diff, %diff, %diff;          // (a-b)^2
    add.f32 %sum, %sum, %diff;            // accumulate

    // idx += stride
    add.u64 %idx, %idx, %stride;
    bra LOOP;

END_LOOP:

    // -------------------------------------------------
    // Block reduction in shared memory (float32)
    // -------------------------------------------------
    .shared .align 4 .f32 sdata[1024];    // max 1024 threads / block

    // store per‑thread sum into shared memory
    .reg .u64 %saddr;
    mul.wide.u32 %saddr, %tid, 4;          // byte offset
    st.shared.f32 [%saddr], %sum;

    bar.sync 0;

    // tree‑reduction
    .reg .u32 %offset;
    mov.u32 %offset, %bsize;
REDUCE:
    shr.u32 %offset, %offset, 1;
    setp.eq.u32 %p_done, %offset, 0;
    @%p_done bra REDUCE_DONE;

    setp.lt.u32 %p_active, %tid, %offset;
    @%p_active {
        .reg .u64 %addr1, %addr2;
        mul.wide.u32 %addr1, %tid, 4;
        mul.wide.u32 %addr2, %tid, 4;
        add.u64 %addr2, %addr2, %offset;
        add.u64 %addr2, %addr2, 0;        // %addr2 = (%tid+%offset)*4

        .reg .f32 %v1, %v2, %vsum;
        ld.shared.f32 %v1, [%addr1];
        ld.shared.f32 %v2, [%addr2];
        add.f32 %vsum, %v1, %v2;
        st.shared.f32 [%addr1], %vsum;
    }
    bar.sync 0;
    bra REDUCE;

REDUCE_DONE:

    // -------------------------------------------------
    // Thread 0 adds block result to global accumulator (float32)
    // -------------------------------------------------
    setp.eq.u32 %p0, %tid, 0;
    @%p0 {
        .reg .f32 %block_sum;
        ld.shared.f32 %block_sum, [sdata];
        atom.global.add.f32 %block_sum, [%out], %block_sum;
    }

    ret;
}
'''
